func TestGateVerdictCoveredWhenATestReaches(t *testing.T) {
	t.Parallel()

	got := gateVerdictFor([]gateReachedTest{gateReachedTestFixture()}, true, 12)

	if got != GateCovered {
		t.Errorf("verdict %q, want %q", got, GateCovered)
